function mergeArray(baseList,localList,remoteList){const idOf=x=>x&&x.id!=null?String(x.id):null;if([...baseList,...localList,...remoteList].some(x=>!idOf(x))){const key=x=>JSON.stringify(x),merged=new Map();remoteList.forEach(x=>merged.set(key(x),x));localList.forEach(x=>merged.set(key(x),x));return Array.from(merged.values()).slice(-4000)}const b=new Map(baseList.map(x=>[idOf(x),x])),l=new Map(localList.map(x=>[idOf(x),x])),r=new Map(remoteList.map(x=>[idOf(x),x])),ids=new Set([...b.keys(),...r.keys(),...l.keys()]),out=[];for(const id of ids){const had=b.has(id),hasL=l.has(id),hasR=r.has(id),base=b.get(id),local=l.get(id),remote=r.get(id),localChanged=hasL!==had||(hasL&&JSON.stringify(local)!==JSON.stringify(base)),remoteChanged=hasR!==had||(hasR&&JSON.stringify(remote)!==JSON.stringify(base));if(!hasL){if(!had){if(hasR)out.push(remote)}else if(remoteChanged&&hasR)out.push(remote)}else if(!hasR){if(!had||localChanged)out.push(local)}else if(localChanged){out.push(local)}else out.push(remote)}return out}
function mergeWorkspace(base,local,remote){const merged={};SYNC_KEYS.forEach(k=>{const b=base?.[k],l=local?.[k],r=remote?.[k];if(Array.isArray(l)||Array.isArray(r)){merged[k]=mergeArray(Array.isArray(b)?b:[],Array.isArray(l)?l:[],Array.isArray(r)?r:[])}else if(l!==undefined&&JSON.stringify(l)!==JSON.stringify(b)){merged[k]=l}else if(r!==undefined){merged[k]=r}});return merged}
function scheduleCloudSave(delay=280){if(!cloud.online||!cloud.authenticated)return;clearTimeout(cloud.syncTimer);cloud.syncTimer=setTimeout(()=>pushCloudState(false),delay);updateCloudChrome()}
async function pushCloudState(initial=false){if(!cloud.online||!cloud.authenticated)return;if(cloud.saving){cloud.pending=true;return}cloud.saving=true;cloud.pending=false;updateCloudChrome();const local=workspacePayload();try{const result=await apiRequest("/workspace",{method:"PUT",body:JSON.stringify({revision:cloud.revision,data:local})});cloud.revision=result.revision;cloud.lastData=result.data;cloud.lastSync=result.updated_at;cloud.lastError=null}catch(error){if(error.status===409){const latest=error.payload||{},remote=latest.data||{},baseline=cloud.lastData||{},merged=mergeWorkspace(baseline,local,remote);cloud.revision=latest.revision||0;cloud.lastData=remote;applyWorkspaceData(merged,false);cloud.pending=JSON.stringify(merged)!==JSON.stringify(remote);if(!initial)toast("Merged a team update","Concurrent workspace changes were reconciled.","warn")}else{cloud.lastError=cloudErrorMessage(error);if(!initial)toast("Cloud sync failed",cloud.lastError,"warn")}}finally{cloud.saving=false;updateCloudChrome();if(cloud.pending){cloud.pending=false;scheduleCloudSave(80)}else{cloud.lastData=workspacePayload();cloud.lastSync=cloud.lastSync||new Date().toISOString()}}}
