function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function localHash(value){let h=2166136261;for(let i=0;i<String(value).length;i++){h^=String(value).charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
function nextId(prefix,list){const nums=(list||[]).map(x=>String(x.id||"").match(/(\d+)$/)).filter(Boolean).map(x=>Number(x[1]));const n=(nums.length?Math.max(...nums):0)+1;return prefix+"-"+String(n).padStart(prefix==="INC"?2:3,"0")}
function initial(name){return String(name||"?").split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function stamp(){return new Date().toISOString()}
function stat(v){const s=String(v||"").toLowerCase();if(/critical|overdue|blocked|maintenance|escalat|variance|high load/.test(s))return"bad";if(/pending|delayed|review|high/.test(s))return"warn";if(/approved|posted|confirmed|available|balanced|verified|nominal|ready|contained|in progress/.test(s))return"good";return"neutral"}
