function applyImportedWorkspaceFile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(String(reader.result||"")),imported=parsed&&parsed.data&&typeof parsed.data==="object"?parsed.data:parsed;if(!imported||typeof imported!=="object"||Array.isArray(imported))throw new Error("The file must contain a workspace JSON object.");const safe={};SYNC_KEYS.forEach(k=>{if(imported[k]!==undefined)safe[k]=imported[k]});["people","tasks","appointments","resources","workforce","messages","incidents","diagnostics","pharmacy","finance","reports","audit"].forEach(k=>{if(safe[k]!==undefined&&!Array.isArray(safe[k]))throw new Error(k+" must be an array.")});if(!confirm("Replace this workspace with the imported JSON snapshot?"))return;applyWorkspaceData(safe,false);audit("Imported workspace JSON",file.name);save();render();toast("JSON imported","The imported workspace will sync when cloud mode is active.")}catch(error){toast("Import failed",error.message||"Invalid JSON file.","warn")}};reader.readAsText(file)}
