const ERP_STORE_KEY="averis-erp-demo-v1";
const erpUi={module:"dashboard",query:"",records:[],summary:null,loadedModule:null,loading:false,editingId:null,formOpen:false,searchTimer:null};
let erpLocalStore=null;
function loadErpLocalStore(){if(erpLocalStore)return erpLocalStore;try{const stored=JSON.parse(localStorage.getItem(ERP_STORE_KEY)||"null");if(stored&&typeof stored==="object"){erpLocalStore=stored;Object.keys(ERP_MODULES).forEach(k=>{if(!Array.isArray(erpLocalStore[k]))erpLocalStore[k]=[]});return erpLocalStore}}catch(error){}erpLocalStore=JSON.parse(JSON.stringify(ERP_SEED));persistErpLocalStore();return erpLocalStore}
function persistErpLocalStore(){try{localStorage.setItem(ERP_STORE_KEY,JSON.stringify(erpLocalStore))}catch(error){}}
function localErpSummary(){const store=loadErpLocalStore(),counts={};Object.keys(ERP_MODULES).forEach(k=>counts[k]=(store[k]||[]).length);const products=store.products||[],low=products.filter(p=>Number(p.quantity||0)<=Number(p.reorder_level||0)).length;let receivables=0,payables=0;(store.invoices||[]).forEach(i=>{const amount=Math.max(0,Number(i.amount||0)-Number(i.paid_amount||0));if(!["paid","void","cancelled"].includes(String(i.status||"").toLowerCase())){if(["payable","outgoing","purchase"].includes(String(i.direction||"receivable").toLowerCase()))payables+=amount;else receivables+=amount}});return{counts,low_stock:low,outstanding_receivables:receivables,outstanding_payables:payables,synthetic_data_only:true}}
function ensureBootstrap(){if(document.getElementById("averis-bootstrap-css"))return;const link=document.createElement("link");link.id="averis-bootstrap-css";link.rel="stylesheet";link.href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css";link.onload=()=>{if(!document.getElementById("averis-app-style-after-bootstrap")){const own=document.createElement("link");own.id="averis-app-style-after-bootstrap";own.rel="stylesheet";own.href="./styles.css?v=29";document.head.appendChild(own)}};document.head.appendChild(link)}
function loadErpModule(force=false){const key=erpUi.module;if(!force&&erpUi.loadedModule===key)return;erpUi.loadedModule=key;erpUi.loading=true;if(key==="dashboard"){if(cloud.online&&cloud.authenticated){Promise.all([apiRequest("/erp/summary"),apiRequest("/erp/products?limit=8")]).then(([summary,products])=>{if(erpUi.module!=="dashboard")return;erpUi.summary=summary;erpUi.records=products.items||[];erpUi.loading=false;render()}).catch(error=>{erpUi.loading=false;toast("ERP summary unavailable",cloudErrorMessage(error),"warn");render()})}else{erpUi.summary=localErpSummary();erpUi.records=(loadErpLocalStore().products||[]).slice(0,8);erpUi.loading=false;render()}return}
if(cloud.online&&cloud.authenticated){apiRequest("/erp/"+encodeURIComponent(key)+"?q="+encodeURIComponent(erpUi.query)+"&limit=500").then(result=>{if(erpUi.module!==key)return;erpUi.records=result.items||[];erpUi.loading=false;render()}).catch(error=>{if(erpUi.module!==key)return;erpUi.loading=false;toast("Could not load "+(ERP_MODULES[key]?.label||"ERP module"),cloudErrorMessage(error),"warn");render()})}
else{const list=(loadErpLocalStore()[key]||[]).slice();const q=erpUi.query.toLowerCase();erpUi.records=q?list.filter(item=>JSON.stringify(item).toLowerCase().includes(q)):list;erpUi.loading=false;render()}}
function erpStatusClass(value){const s=String(value||"").toLowerCase();if(/active|paid|complete|received|delivered|won|pass|in service|posted/.test(s))return"good";if(/overdue|critical|fail|at risk|hold|blocked|needs repair/.test(s))return"bad";if(/pending|draft|progress|proposal|ordered|qualified|waiting|partial/.test(s))return"warn";return"neutral"}
function erpValue(key,value){if(value===undefined||value===null||value==="")return'<span class="erp-muted">—</span>';if(key==="status"||key==="stage"||key==="result"||key==="condition"||key==="direction")return'<span class="erp-status '+erpStatusClass(value)+'">'+esc(String(value))+'</span>';if(["selling_price","unit_cost","total","amount","paid_amount","lifetime_value","value","budget","salary"].includes(key)&&!Number.isNaN(Number(value)))return esc(new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(Number(value)));if(key==="progress")return'<div class="erp-progress"><span style="width:'+Math.max(0,Math.min(100,Number(value)||0))+'%"></span></div><small>'+esc(String(value))+'%</small>';return esc(String(value))}
function erpField(field,value){const id="erp-field-"+field.key,val=value===undefined||value===null?(field.value||""):String(value);let control;if(field.type==="select"){control='<select class="form-select erp-field-control" id="'+id+'" name="'+field.key+'" data-erp-field="'+field.key+'" '+(field.required?"required":"")+'>'+(field.options||[]).map(o=>'<option value="'+esc(o)+'" '+(String(o)===val?"selected":"")+'>'+esc(o)+'</option>').join("")+'</select>'}else control='<input class="form-control erp-field-control" id="'+id+'" name="'+field.key+'" data-erp-field="'+field.key+'" type="'+(field.type||"text")+'" value="'+esc(val)+'" '+(field.required?"required":"")+' '+(field.type==="number"?'min="0" step="any"':'')+' maxlength="500" '+(field.required?'aria-required="true"':'')+'/>';return '<div class="col-12 col-md-6"><label class="form-label erp-form-label" for="'+id+'">'+esc(field.label)+(field.required?' <span aria-hidden="true">*</span>':'')+'</label>'+control+'</div>'}
function erpRecordForm(){const module=ERP_MODULES[erpUi.module],record=erpUi.editingId?erpUi.records.find(r=>r.id===erpUi.editingId):null;if(!erpUi.formOpen||!module)return"";return'<section class="erp-form-card card mb-3"><div class="card-body"><div class="d-flex align-items-start justify-content-between gap-2 mb-3"><div><span class="erp-eyebrow">'+(record?"EDIT RECORD":"NEW RECORD")+'</span><h3 class="h5 mb-1">'+(record?"Edit "+esc(module.label):"Create "+esc(module.label))+'</h3><p class="small text-secondary mb-0">Changes are stored in the shared SQL database when cloud mode is connected.</p></div>'+btn("erp-cancel-form","Cancel","ghost small")+'</div><form id="erp-record-form" data-erp-form="'+erpUi.module+'" data-erp-id="'+esc(record?.id||"")+'" class="row g-3" novalidate>'+module.fields.map(f=>erpField(f,record?.[f.key])).join("")+'<div class="col-12 d-flex flex-wrap gap-2"><button class="button primary" type="submit">'+(record?"Save changes":"Create record")+'</button><button class="button ghost" type="button" data-action="erp-cancel-form">Cancel</button></div></form></div></section>'}
function erpModuleTabs(){const keys=Object.keys(ERP_MODULES);return'<div class="erp-module-tabs" role="navigation" aria-label="ERP modules"><button class="erp-tab '+(erpUi.module==="dashboard"?"active":"")+'" data-action="erp-module:dashboard" type="button">⌂ Overview</button>'+keys.map(k=>'<button class="erp-tab '+(erpUi.module===k?"active":"")+'" data-action="erp-module:'+k+'" type="button">'+esc(ERP_MODULES[k].label)+'</button>').join("")+'</div>'}
function renderErpDashboard(){const summary=erpUi.summary||localErpSummary(),counts=summary.counts||{},cards=[["Total records",Object.values(counts).reduce((a,b)=>a+Number(b||0),0),"Across 15 ERP modules"],["Inventory alerts",summary.low_stock||0,"Products at or below reorder level"],["Receivables",new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(summary.outstanding_receivables||0),"Outstanding customer invoices"],["Payables",new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(summary.outstanding_payables||0),"Outstanding supplier invoices"]];return'<section class="erp-kpi-grid">'+cards.map((c,i)=>'<article class="erp-kpi-card"><span>'+esc(c[0])+'</span><strong>'+esc(String(c[1]))+'</strong><small>'+esc(c[2])+'</small><i class="erp-kpi-orb orb-'+i+'"></i></article>').join("")+'</section><section class="erp-dashboard-grid"><section class="card erp-panel"><div class="card-body"><div class="erp-section-head"><div><span class="erp-eyebrow">YOUR BUSINESS</span><h3 class="h5 mb-1">All departments, connected</h3><p class="small text-secondary mb-0">Switch modules without leaving the operating workspace.</p></div><span class="erp-live-indicator">'+(cloud.online&&cloud.authenticated?"LIVE API":"LOCAL DEMO")+'</span></div><div class="erp-launch-grid">'+Object.keys(ERP_MODULES).map((k,i)=>'<button type="button" class="erp-launch-card" data-action="erp-module:'+k+'"><span class="erp-launch-icon icon-'+(i%6)+'">'+["▦","⇄","▤","◎","↗","₹","♙","◉","⌁","◇","≋","?","⚙","↕","✓"][i]+'</span><b>'+esc(ERP_MODULES[k].label)+'</b><small>'+esc(ERP_MODULES[k].description)+'</small><span class="erp-launch-count">'+Number(counts[k]||0)+' records <span>↗</span></span></button>').join("")+'</div></div></section><aside class="card erp-panel"><div class="card-body"><div class="erp-section-head"><div><span class="erp-eyebrow">RECENT INVENTORY</span><h3 class="h5 mb-1">Stock watch</h3><p class="small text-secondary mb-0">Low stock stands out for quick action.</p></div>'+btn("erp-module:products","Open inventory","small ghost")+'</div><div class="erp-stock-list">'+(erpUi.records||[]).slice(0,7).map(p=>'<div class="erp-stock-row"><span class="erp-stock-icon">▦</span><div><b>'+esc(p.name||p.sku||"Product")+'</b><small>'+esc(p.sku||p.id||"")+'</small></div><span class="erp-stock-qty '+(Number(p.quantity||0)<=Number(p.reorder_level||0)?"low":"")+'">'+esc(String(p.quantity??0))+' on hand</span></div>').join("")+'</div>'+btn("erp-module:products","Review all inventory","small ghost")+'</div></aside></section><section class="erp-integrations-strip"><div><span class="erp-eyebrow">ONE DATA LAYER</span><h3>Shared accounts · SQL persistence · JSON REST · live revision checks</h3><p>Python API with SQLite locally, MySQL/PostgreSQL support, tests, Docker and cloud deploy workflows.</p></div>'+btn("go-workspace","Workspace & team","primary")+'</section>'}
function renderErpRows(){const module=ERP_MODULES[erpUi.module],records=erpUi.records||[];if(erpUi.loading)return'<tr><td colspan="'+(module.columns.length+2)+'"><div class="erp-loading"><span></span> Loading '+esc(module.label)+'…</div></td></tr>';if(!records.length)return'<tr><td colspan="'+(module.columns.length+2)+'"><div class="erp-empty"><b>No records found</b><span>Create a record or change the search.</span></div></td></tr>';return records.map(record=>'<tr class="erp-row" data-erp-row-text="'+esc(Object.values(record).join(" ").toLowerCase())+'">'+module.columns.map(k=>'<td>'+erpValue(k,record[k])+'</td>').join("")+'<td><div class="erp-row-actions"><button class="button small ghost" data-action="erp-edit:'+erpUi.module+':'+encodeURIComponent(record.id)+'" type="button">Edit</button><button class="button small danger" data-action="erp-delete:'+erpUi.module+':'+encodeURIComponent(record.id)+'" type="button">Delete</button></div></td></tr>').join("")}
function renderErpList(){const module=ERP_MODULES[erpUi.module];return'<section class="erp-table-panel card"><div class="card-body"><div class="erp-list-toolbar"><div><span class="erp-eyebrow">DATA WORKSPACE</span><h3 class="h5 mb-1">'+esc(module.label)+'</h3><p class="small text-secondary mb-0">'+esc(module.description)+'</p></div><div class="erp-list-actions">'+btn("erp-create","＋ New record","primary")+btn("erp-export","Export JSON","ghost")+'</div></div>'+erpRecordForm()+'<div class="erp-searchbar"><label for="erp-search-query">Search this module</label><div class="erp-search-controls"><input class="form-control" id="erp-search-query" value="'+esc(erpUi.query)+'" placeholder="Search '+esc(module.label.toLowerCase())+'…"><button type="button" class="button ghost" data-action="erp-search">Search</button><button type="button" class="button ghost" data-action="erp-clear-search">Clear</button><span class="erp-record-count">'+(erpUi.records||[]).length+' records</span></div></div><div class="table-responsive erp-table-scroll"><table class="table table-hover align-middle erp-table"><thead><tr>'+module.columns.map(k=>'<th scope="col">'+esc(k.replaceAll("_"," "))+'</th>').join("")+'<th scope="col">Actions</th></tr></thead><tbody>'+renderErpRows()+'</tbody></table></div><div class="erp-list-foot"><span><i></i> '+(cloud.online&&cloud.authenticated?"Server-backed records":"Browser demo records")+'</span><span>Tenant-scoped · JSON validated · audited</span></div></div></section>'}
function renderErpSuite(){ensureBootstrap();const actions=erpUi.module==="dashboard"?btn("erp-module:products","＋ Add product","primary")+btn("erp-export-all","Export ERP JSON","ghost"):btn("erp-create","＋ New record","primary")+btn("erp-export","Export JSON","ghost");return'<div class="erp-suite container-fluid px-0">'+page("erp",actions)+erpModuleTabs()+(erpUi.module==="dashboard"?renderErpDashboard():renderErpList())+'<p class="erp-synthetic-note">AVERIS ERP Suite · operational demo data only. Do not enter real patient data, financial secrets or sensitive personal information.</p></div>'}
function loadErpModule(force=false){const key=erpUi.module;if(!force&&erpUi.loadedModule===key)return;erpUi.loadedModule=key;erpUi.loading=true;if(key==="dashboard"){if(cloud.online&&cloud.authenticated){Promise.all([apiRequest("/erp/summary"),apiRequest("/erp/products?limit=8")]).then(([summary,products])=>{if(erpUi.module!=="dashboard")return;erpUi.summary=summary;erpUi.records=products.items||[];erpUi.loading=false;render()}).catch(error=>{erpUi.loading=false;toast("ERP summary unavailable",cloudErrorMessage(error),"warn");render()})}else{erpUi.summary=localErpSummary();erpUi.records=(loadErpLocalStore().products||[]).slice(0,8);erpUi.loading=false;render()}return}if(cloud.online&&cloud.authenticated){apiRequest("/erp/"+encodeURIComponent(key)+"?q="+encodeURIComponent(erpUi.query)+"&limit=500").then(result=>{if(erpUi.module!==key)return;erpUi.records=result.items||[];erpUi.loading=false;render()}).catch(error=>{if(erpUi.module!==key)return;erpUi.loading=false;toast("Could not load "+(ERP_MODULES[key]?.label||"ERP module"),cloudErrorMessage(error),"warn");render()})}else{const list=(loadErpLocalStore()[key]||[]).slice(),q=erpUi.query.toLowerCase();erpUi.records=q?list.filter(item=>JSON.stringify(item).toLowerCase().includes(q)):list;erpUi.loading=false;render()}}
function saveErpRecord(moduleKey,recordKey,payload){if(cloud.online&&cloud.authenticated){const path="/erp/"+encodeURIComponent(moduleKey)+(recordKey?"/"+encodeURIComponent(recordKey):"");return apiRequest(path,{method:recordKey?"PUT":"POST",body:JSON.stringify(payload)}).then(result=>{erpUi.formOpen=false;erpUi.editingId=null;erpUi.query="";erpUi.loadedModule=null;loadErpModule(true);apiRequest("/erp/summary").then(s=>erpUi.summary=s).catch(()=>{});toast(recordKey?"Record updated":"Record created",ERP_MODULES[moduleKey].label+" saved to the shared database.");return result}).catch(error=>{toast("Save failed",cloudErrorMessage(error),"warn");throw error})}
const store=loadErpLocalStore();let record;if(recordKey){const idx=(store[moduleKey]||[]).findIndex(x=>x.id===recordKey);if(idx<0){toast("Record not found","It may have been deleted.","warn");return}record=Object.assign({},store[moduleKey][idx],payload,{updated_at:new Date().toISOString()});store[moduleKey][idx]=record}else{record=Object.assign({id:(ERP_MODULES[moduleKey].prefix||moduleKey.toUpperCase().slice(0,3))+"-"+Date.now().toString(36).toUpperCase(),created_at:new Date().toISOString()},payload);store[moduleKey].unshift(record)}persistErpLocalStore();erpUi.formOpen=false;erpUi.editingId=null;erpUi.records=store[moduleKey].slice();erpUi.summary=localErpSummary();erpUi.loadedModule=moduleKey;render();toast(recordKey?"Record updated":"Record created",ERP_MODULES[moduleKey].label+" saved locally.");return Promise.resolve(record)}
function deleteErpRecord(moduleKey,recordKey){if(!confirm("Delete "+(ERP_MODULES[moduleKey]?.label||"ERP")+" record "+recordKey+"?"))return;if(cloud.online&&cloud.authenticated){apiRequest("/erp/"+encodeURIComponent(moduleKey)+"/"+encodeURIComponent(recordKey),{method:"DELETE"}).then(()=>{erpUi.query="";loadErpModule(true);apiRequest("/erp/summary").then(s=>erpUi.summary=s).catch(()=>{});toast("Record deleted",recordKey+" removed from the database.")}).catch(error=>toast("Delete failed",cloudErrorMessage(error),"warn"));return}const store=loadErpLocalStore();store[moduleKey]=(store[moduleKey]||[]).filter(x=>x.id!==recordKey);persistErpLocalStore();erpUi.records=store[moduleKey].slice();erpUi.summary=localErpSummary();render();toast("Record deleted",recordKey+" removed from this browser.")}
function saveErpForm(form){const moduleKey=form.dataset.erpForm,recordKey=form.dataset.erpId||"";if(!ERP_MODULES[moduleKey])return;const payload={};form.querySelectorAll("[data-erp-field]").forEach(input=>{let value=input.value;if(input.type==="number")value=value===""?null:Number(value);payload[input.dataset.erpField]=value});for(const field of ERP_MODULES[moduleKey].fields.filter(f=>f.required)){if(payload[field.key]===null||payload[field.key]===undefined||String(payload[field.key]).trim()===""){inputFocus(form.querySelector('[data-erp-field="'+field.key+'"]'));toast("Required field",field.label+" is required.","warn");return}}if(moduleKey==="products"&&payload.sku)payload.sku=payload.sku.trim().toUpperCase();saveErpRecord(moduleKey,recordKey,payload)}
function inputFocus(input){if(input){input.focus();input.setAttribute("aria-invalid","true")}}
function erpAction(action){if(action.startsWith("erp-module:")){const key=action.split(":")[1];if(key!=="dashboard"&&!ERP_MODULES[key])return;erpUi.module=key;erpUi.query="";erpUi.formOpen=false;erpUi.editingId=null;erpUi.loadedModule=null;render();loadErpModule(true);return true}if(action==="erp-create"){if(erpUi.module==="dashboard")erpUi.module="products";erpUi.formOpen=true;erpUi.editingId=null;render();return true}if(action==="erp-cancel-form"){erpUi.formOpen=false;erpUi.editingId=null;render();return true}if(action.startsWith("erp-edit:")){const parts=action.split(":");erpUi.module=parts[1];erpUi.editingId=decodeURIComponent(parts.slice(2).join(":"));erpUi.formOpen=true;erpUi.loadedModule=null;loadErpModule(true);render();return true}if(action.startsWith("erp-delete:")){const parts=action.split(":");deleteErpRecord(parts[1],decodeURIComponent(parts.slice(2).join(":")));return true}if(action==="erp-search"){erpUi.query=document.getElementById("erp-search-query")?.value||"";loadErpModule(true);return true}if(action==="erp-clear-search"){erpUi.query="";const input=document.getElementById("erp-search-query");if(input)input.value="";loadErpModule(true);return true}if(action==="erp-export"){exportJson("averis-erp-"+erpUi.module+".json",{schemaVersion:1,module:erpUi.module,exportedAt:stamp(),items:erpUi.records||[]});return true}if(action==="erp-export-all"){const data=cloud.online&&cloud.authenticated?null:loadErpLocalStore();if(data){exportJson("averis-erp-backup.json",{schemaVersion:1,exportedAt:stamp(),data});return true}Promise.all(Object.keys(ERP_MODULES).map(k=>apiRequest("/erp/"+k+"?limit=500").then(r=>[k,r.items||[]]))).then(pairs=>{const out={};pairs.forEach(([k,v])=>out[k]=v);exportJson("averis-erp-backup.json",{schemaVersion:1,exportedAt:stamp(),data:out})}).catch(error=>toast("Export failed",cloudErrorMessage(error),"warn"));return true}return false}

function render(){const authPage=route==="login"||route==="register";if(!state.session.authenticated&&!authPage)route="login";state.theme="dark";document.documentElement.dataset.theme="dark";document.documentElement.style.colorScheme="dark";const themeMeta=document.querySelector('meta[name="theme-color"]');if(themeMeta)themeMeta.content="#07111f";document.body.classList.toggle("focus-mode",state.focus);document.body.classList.toggle("compact-mode",state.compact);document.body.classList.toggle("auth-mode",authPage);const view=views[route]||views.today;document.getElementById("workspace-root").innerHTML=view();if(route==="workspace")loadServerActivity();if(route==="erp"){ensureBootstrap();if(erpUi.loadedModule!==erpUi.module)loadErpModule(false)}const crumb=document.getElementById("crumb-current");if(crumb)crumb.textContent=ROUTES[route]?.[0]||"Overview";const profileName=document.getElementById("profile-name");if(profileName)profileName.textContent=state.profile.name;const profileRole=document.getElementById("profile-role");if(profileRole)profileRole.textContent=state.profile.role;document.querySelectorAll(".avatar-main").forEach(x=>x.textContent=initial(state.profile.name));document.querySelectorAll(".nav-item,.site-nav-link").forEach(x=>x.classList.toggle("active",x.dataset.route===route));document.getElementById("site-more-toggle")?.classList.toggle("active",["insights","reports","erp","workspace"].includes(route));const unread=state.messages.filter(m=>!m.read).length;document.getElementById("notification-count").textContent=state.notifications?unread:0;const dots={messages:state.notifications?unread:0,queue:state.tasks.filter(t=>/blocked|overdue/i.test(t.status)).length,incidents:state.incidents.filter(i=>i.state!=="Resolved").length,pharmacy:state.pharmacy.filter(p=>p.qty<p.minimum).length};document.querySelectorAll("[data-dot]").forEach(x=>x.classList.toggle("show",dots[x.dataset.dot]>0));document.title="AVERIS — "+(ROUTES[route]?.[0]||"Today")+" · by Mahi";syncHeaderHeight();updateCloudChrome()}
function pulse(){const values=[40,48,44,58,51,68,61,75,69,82,74,88],w=760,h=220,p=28,pts=values.map((v,i)=>[p+i*(w-p*2)/(values.length-1),h-p-(v-20)/80*(h-p*2)]),line=pts.map((x,i)=>(i?"L":"M")+x[0].toFixed(1)+" "+x[1].toFixed(1)).join(" ");return'<svg viewBox="0 0 '+w+' '+h+'" aria-label="Operating pulse chart"><defs><linearGradient id="pulse" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#5ef0da"/><stop offset=".55" stop-color="#7593ff"/><stop offset="1" stop-color="#ffc86b"/></linearGradient></defs><path d="M28 48H732M28 98H732M28 148H732M28 198H732" stroke="currentColor" opacity=".08"/><path d="'+line+'" fill="none" stroke="url(#pulse)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>'+pts.map(x=>'<circle cx="'+x[0]+'" cy="'+x[1]+'" r="3.5" fill="var(--solid)" stroke="#5ef0da" stroke-width="2"/>').join("")+"</svg>"}

function authShell(mode){
const register=mode==="register",cloudReady=cloud.online;
const title=register?"Create your AVERIS workspace":"Welcome back to AVERIS";
const subtitle=register?(cloudReady?"Create an account for your shared organization.":"Build a local synthetic demo in this browser."):(cloudReady?"Sign in to your server-backed workspace.":"Sign in to your local operations workspace.");
const art=register?"https://res.cloudinary.com/casden-edito/images/c_scale%2Cw_2048%2Ch_1442%2Cdpr_2/f_auto%2Cq_auto/v1699015961/prod/recrutement-FPH/recrutement-FPH.jpg?_i=AA":"https://www.ihhhealthcare.com/images/default-source/ihh/occ-2.jpg?sfvrsn=2801dfb4_1",artFallback=register?"./assets/care-team.svg":"./assets/healthcare-scene.svg";
const orgField=register?'<div class="field"><label for="auth-organization">Organization name</label><input class="input" id="auth-organization" autocomplete="organization" placeholder="Operations team" minlength="2" maxlength="120" required></div>':"";
const form=register?'<form class="auth-form" data-auth-form="register" novalidate><div class="field"><label for="auth-name">Full name</label><input class="input" id="auth-name" autocomplete="name" placeholder="Your name" minlength="2" maxlength="100" required></div>'+orgField+'<div class="field"><label for="auth-email">Email</label><input class="input" id="auth-email" type="email" autocomplete="email" placeholder="you@company.com" required></div><div class="field"><label for="auth-password">Password</label><div class="password-wrap"><input class="input" id="auth-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" placeholder="At least 12 characters" required><button class="password-toggle" data-action="toggle-password" type="button" aria-label="Show password">◉</button></div></div><div class="field"><label for="auth-confirm">Confirm password</label><input class="input" id="auth-confirm" type="password" autocomplete="new-password" minlength="12" placeholder="Repeat password" required></div><label class="check-row"><input id="auth-local-only" type="checkbox" required><span>I will use synthetic records only; this is not a clinical system.</span></label><button class="button primary auth-submit" type="submit">'+(cloudReady?"Create account":"Create local account")+'</button></form>':'<form class="auth-form" data-auth-form="login" novalidate><div class="field"><label for="auth-email">Email</label><input class="input" id="auth-email" type="email" autocomplete="email" placeholder="you@company.com" required></div><div class="field"><label for="auth-password">Password</label><div class="password-wrap"><input class="input" id="auth-password" type="password" autocomplete="current-password" placeholder="Your password" required><button class="password-toggle" data-action="toggle-password" type="button" aria-label="Show password">◉</button></div></div><label class="check-row"><input id="auth-remember" type="checkbox" checked><span>Keep this browser session active</span></label><button class="button primary auth-submit" type="submit">'+(cloudReady?"Sign in securely":"Sign in locally")+'</button></form>';
const opposite=register?'<button class="button ghost" data-action="open-login" type="button">Already have an account</button>':'<button class="button ghost" data-action="open-register" type="button">Create an account</button>';
const demo=register?"":(cloudReady?'<div class="auth-demo-actions"><button class="button primary" data-action="cloud-demo" type="button">Launch isolated cloud demo</button><button class="button ghost" data-action="login-demo" type="button">Open browser-only demo</button></div>':'<button class="button ghost" data-action="login-demo" type="button">Open browser-only demo</button>');
return '<section class="auth-screen"><div class="auth-stage"><div class="auth-visual"><div class="auth-image-frame"><img src="'+art+'" data-photo="'+art+'" data-fallback="'+artFallback+'" onerror="this.onerror=null;this.src=this.dataset.fallback" alt="Representative healthcare operations environment" loading="eager" fetchpriority="high" decoding="async"><span class="image-badge"><i></i> SYNTHETIC WORKSPACE</span></div><div class="auth-visual-copy"><span class="eyebrow">AVERIS · BY MAHI</span><h2>Operational clarity, <span>without the clinical risk.</span></h2><p>Coordinate synthetic records, work, capacity, messages, incidents and reporting from one operations workspace.</p><div class="auth-pills"><span>19 workspaces</span><span>'+(cloudReady?"Server sync":"Offline preview")+'</span><span>Synthetic data only</span></div></div></div><div class="auth-card"><span class="eyebrow">'+(register?"ACCOUNT SETUP":(cloudReady?"SECURE SIGN IN":"LOCAL ACCESS"))+'</span><h1>'+title+'</h1><p>'+subtitle+'</p>'+form+demo+'<div class="auth-divider"><span>'+(cloudReady?"server-backed workspace":"local browser workspace")+'</span></div><div class="auth-switch">'+opposite+'</div><div class="auth-footnote">'+(cloudReady?"Server-side account and workspace persistence · synthetic records only":"Synthetic demo only · local browser storage")+'</div></div></div></section>';
}
function loginView(){return authShell("login")}
function registerView(){return authShell("register")}
async function loginNow(){
const email=(document.getElementById("auth-email")?.value||"").trim().toLowerCase(),password=document.getElementById("auth-password")?.value||"";
if(!email||!password){toast("Sign in needs both fields","Enter your email and password.","warn");return}
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast("Email looks invalid","Enter a valid email address.","warn");return}
if(cloud.online){try{await cloudSignIn(email,password)}catch(error){toast("Sign in failed",cloudErrorMessage(error),"warn")}return}
if(email!==String(state.account.email||"").toLowerCase()||localHash(password)!==state.account.passHash){toast("Sign in failed","That local demo account does not match. Use the demo account or register locally.","warn");return}
state.profile.name=state.account.name;state.session={authenticated:true,lastLogin:stamp()};audit("Signed in","Local demo");save();navigate("today");toast("Welcome back",state.profile.name+" · local demo active");
}
async function launchCloudDemo(){const button=document.querySelector('[data-action="cloud-demo"]');if(button){button.disabled=true;button.textContent="Preparing demo…"}try{const identity=await apiRequest("/auth/demo",{method:"POST",body:JSON.stringify({})});setCloudIdentity(identity);cloud.demoWorkspace=true;await hydrateCloudWorkspace();navigate("today");toast("Isolated demo ready","A private sample organization and seeded ERP data are ready.")}catch(error){toast("Demo could not start",cloudErrorMessage(error),"warn")}finally{const next=document.querySelector('[data-action="cloud-demo"]');if(next){next.disabled=false;next.textContent="Launch isolated demo workspace"}}}
function loginDemo(){if(cloud.online){toast("Cloud sign-in active","Use a registered workspace account.","warn");return}state.account={name:"Mahi",email:"mahi@averis.local",passHash:localHash("Mahi@580")};state.profile.name="Mahi";state.profile.role="Control room owner";state.session={authenticated:true,lastLogin:stamp()};audit("Used demo account","Local demo");save();navigate("today");toast("Demo account active","mahi@averis.local")}
async function registerNow(){
const name=(document.getElementById("auth-name")?.value||"").trim(),email=(document.getElementById("auth-email")?.value||"").trim().toLowerCase(),password=document.getElementById("auth-password")?.value||"",confirmPassword=document.getElementById("auth-confirm")?.value||"",organizationName=(document.getElementById("auth-organization")?.value||"").trim(),accepted=document.getElementById("auth-local-only")?.checked;
if(name.length<2){toast("Name required","Enter at least 2 characters.","warn");return}
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast("Email required","Enter a valid email format.","warn");return}
if(password.length<12){toast("Password too short","Use at least 12 characters.","warn");return}
if(password!==confirmPassword){toast("Passwords do not match","Re-enter the same password.","warn");return}
if(!accepted){toast("Synthetic-data boundary required","Confirm that you will use synthetic records only.","warn");return}
if(cloud.online){if(organizationName.length<2){toast("Organization required","Enter an organization name.","warn");return}try{await cloudRegister(name,email,password,organizationName)}catch(error){toast("Registration failed",cloudErrorMessage(error),"warn")}return}
state.account={name,email,passHash:localHash(password)};state.profile.name=name;state.profile.role="Control room owner";state.session={authenticated:true,lastLogin:stamp()};audit("Registered local account",email);save();navigate("today");toast("Local workspace created","Account saved locally in this browser.");
}
async function logout(){
if(cloud.online&&cloud.authenticated){try{await apiRequest("/auth/logout",{method:"POST",body:JSON.stringify({})})}catch(error){cloud.lastError=cloudErrorMessage(error)}}
if(cloud.pollTimer)clearInterval(cloud.pollTimer);clearTimeout(cloud.syncTimer);cloud.authenticated=false;cloud.user=null;cloud.organization=null;cloud.revision=0;cloud.lastData=null;state.session.authenticated=false;try{localStorage.removeItem(KEY)}catch(e){}closeAll();route="login";location.hash="/login";render();updateCloudChrome();toast("Signed out","Your server session has been ended.")
}
